         {
             req->handle   = wine_server_obj_handle( handle );
-            req->affinity = *(PDWORD_PTR)info;
+            req->affinity = affinity_mask;
             req->mask     = SET_PROCESS_INFO_AFFINITY;
             ret = wine_server_call( req );
         }

